import { Router, Request, Response, NextFunction } from "express";
import { prisma } from "../../config/database";
import { NotFoundError } from "../../shared/errors";
import { authenticate } from "../../middleware/auth";
import { authorize } from "../../middleware/authorize";

const router = Router();

// 1. Get All Theatres
router.get("/", async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { city, status } = req.query;

    const theatres = await prisma.theatre.findMany({
      where: {
        ...(city ? { city: String(city) } : {}),
        ...(status ? { status: status as any } : {})
      },
      include: {
        screens: {
          select: { id: true, name: true, capacity: true }
        }
      }
    });

    return res.json({
      success: true,
      count: theatres.length,
      data: { theatres }
    });
  } catch (error) {
    next(error);
  }
});

// 2. Get Theatre by ID
router.get("/:id", async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { id } = req.params;
    const theatre = await prisma.theatre.findUnique({
      where: { id },
      include: {
        screens: {
          include: { seats: true }
        },
        shows: {
          where: { startTime: { gte: new Date() } },
          include: { movie: true }
        }
      }
    });

    if (!theatre) {
      throw new NotFoundError("Theatre", id);
    }

    return res.json({
      success: true,
      data: { theatre }
    });
  } catch (error) {
    next(error);
  }
});

// 3. Admin: Create Theatre
router.post("/", authenticate, authorize("SUPER_ADMIN", "ADMIN"), async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { name, address, city, state, phone, status, totalScreens } = req.body;

    const theatre = await prisma.theatre.create({
      data: {
        name,
        address: address || `${name}, ${city || "Hyderabad"}`,
        city: city || "Hyderabad",
        state: state || "Telangana",
        phone: phone || null,
        status: status || "ACTIVE"
      }
    });

    // Create default screens if requested
    const numScreens = Math.max(1, Number(totalScreens) || 3);
    for (let i = 1; i <= numScreens; i++) {
      try {
        await prisma.screen.create({
          data: {
            theatreId: theatre.id,
            name: `Screen ${i}`,
            capacity: 150
          }
        });
      } catch {}
    }

    return res.status(201).json({
      success: true,
      message: "Theatre created successfully",
      data: { theatre }
    });
  } catch (error) {
    next(error);
  }
});

// 4. Create Screen for Theatre
router.post("/:theatreId/screens", authenticate, authorize("SUPER_ADMIN", "ADMIN", "THEATRE_ADMIN"), async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { theatreId } = req.params;
    const { name, capacity } = req.body;

    const screen = await prisma.screen.create({
      data: {
        theatreId,
        name,
        capacity: Number(capacity) || 100
      }
    });

    return res.status(201).json({
      success: true,
      message: "Screen created successfully",
      data: { screen }
    });
  } catch (error) {
    next(error);
  }
});

// 5. Get Bank Accounts for Theatre (Authorized)
router.get("/:theatreId/bank-accounts", authenticate, authorize("SUPER_ADMIN", "ADMIN", "THEATRE_ADMIN"), async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { theatreId } = req.params;
    const accounts = await prisma.theatreBankAccount.findMany({
      where: { theatreId, isActive: true }
    });

    return res.json({
      success: true,
      data: { accounts }
    });
  } catch (error) {
    next(error);
  }
});

// 6. Admin: Update Theatre
router.put("/:id", authenticate, authorize("SUPER_ADMIN", "ADMIN"), async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { id } = req.params;
    let targetId = id;
    let existing = await prisma.theatre.findUnique({ where: { id } });
    if (!existing) {
      existing = await prisma.theatre.findFirst({
        where: {
          OR: [
            { id: `th_${id}` },
            { name: req.body?.name || id }
          ]
        }
      });
      if (existing) targetId = existing.id;
    }

    const theatre = await prisma.theatre.update({
      where: { id: targetId },
      data: req.body
    });

    return res.json({
      success: true,
      message: "Theatre updated successfully",
      data: { theatre }
    });
  } catch (error) {
    next(error);
  }
});

// 7. Admin: Delete Theatre
router.delete("/:id", authenticate, authorize("SUPER_ADMIN", "ADMIN"), async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { id } = req.params;
    let targetId = id;
    let existing = await prisma.theatre.findUnique({ where: { id } });
    if (!existing) {
      existing = await prisma.theatre.findFirst({
        where: {
          OR: [
            { id: `th_${id}` },
            { name: id }
          ]
        }
      });
      if (existing) targetId = existing.id;
    }

    await prisma.theatre.delete({ where: { id: targetId } }).catch(async () => {
      await prisma.theatre.update({ where: { id: targetId }, data: { status: "INACTIVE" } });
    });

    return res.json({
      success: true,
      message: "Theatre removed successfully"
    });
  } catch (error) {
    next(error);
  }
});

export default router;
